    @EventHandler
    public RoleAssignment handle( UpdateRoleAssignmentEvent event) {
    	entityManager.merge(new RoleAssignment(event.getRoleAssignmentId(), event.getEffectiveFrom(), event.getEffectiveTo(), event.getPerson(), event.getRole(), event.getGovernanceBody(), event.getOrganization()));
    }
    
    /*
     * @param	event DeleteRoleAssignmentEvent
     */
    @EventHandler
    public void on( DeleteRoleAssignmentEvent event) {
    	RoleAssignment entity = new RoleAssignment();
   
    	// ------------------------------------------
    	// apply the RoleAssignmentId
    	// ------------------------------------------
    	entity.setRoleAssignmentId( event.getRoleAssignmentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
